function active(){try{return !!activeCase&&activeCase.id===CASE_ID}catch(_){return false}}
function complete(){try{return !!caseIsComplete()}catch(_){return !!(state?.finalized||state?.research?.finalized)}}
function E(x){try{return typeof esc==='function'?esc(x==null?'':String(x)):String(x??'')}catch(_){return String(x??'')}}
function registerTranslations(){try{const core=window.MolPathI18n;if(!core||!core.dict)return false;Object.entries(TRANSLATIONS).forEach(([lang,map])=>{const d=core.dict[lang]=core.dict[lang]||{};Object.entries(map).forEach(([src,val])=>{if(!Object.prototype.hasOwnProperty.call(d,src))d[src]=val})});return true}catch(e){console.warn('[RES_VAL_001] i18n registration failed',e);return false}}
function registerDeepDive(){try{if(typeof DEEP_DIVE_MAP_V17==='undefined'||typeof DEEP_DIVE_CASES_V17==='undefined')return false;const d=JSON.parse(JSON.stringify(DEEP));const i=DEEP_DIVE_CASES_V17.findIndex(x=>x&&x.case_id===CASE_ID);if(i>=0)DEEP_DIVE_CASES_V17[i]=d;else DEEP_DIVE_CASES_V17.push(d);DEEP_DIVE_MAP_V17[CASE_ID]=d;return true}catch(e){console.warn('[RES_VAL_001] deep-dive registration failed',e);return false}}
function patchCase(){try{const c=(cases||[]).find(x=>x&&x.id===CASE_ID);if(!c)return false;c.deep_dive=true;c.title=C.case_title;c.short=C.case_short;c.difficulty='advanced';c.estimated_time_min='15–18';c.research_takehome=C.takehome;c.tags=Array.from(new Set([].concat(c.tags||[],['HGSOC','CCNE1','RNA-seq','qPCR','FISH','Cyclin E1','Validation','Reproducibility']).filter(Boolean)));return true}catch(e){console.warn('[RES_VAL_001] case patch failed',e);return false}}
function asset(title,src,cls=''){return `<figure class="rv1-asset ${cls}"><figcaption>${E(title)}</figcaption><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${E(title)}"></a><div class="rv1-prov">${E(C.prov)}</div></figure>`}
function block(title,items,cls=''){return `<div class="rv1-block ${cls}"><div class="rv1-head"><h4>${E(title)}</h4><span class="rv1-pill">${E(C.badge)}</span></div><div class="rv1-grid ${items.length===1?'single':''}">${items.join('')}</div></div>`}
function inject(html,addon){if(!html||!addon)return html;const i=html.lastIndexOf('</section>');return i>=0?html.slice(0,i)+addon+html.slice(i):html+addon}
function addon(){if(!active()||!state)return '';switch(state.step){case 'project_idea':return block(C.b1,[asset(C.cap1,ASSETS.a1,'wide')]);case 'context':return block(C.b2,[asset(C.cap2,ASSETS.a2),asset(C.cap3,ASSETS.a3)]);case 'methods':return block(C.b3,[asset(C.cap4,ASSETS.a4,'wide')],'rv1-plan');case 'analysis':return block(C.b4,[asset(C.cap5,ASSETS.a5),asset(C.cap6,ASSETS.a6),asset(C.cap7,ASSETS.a7,'wide')],'rv1-validation');case 'feedback':return complete()?block(C.b5,[asset(C.cap8,ASSETS.a8,'wide')],'rv1-complete'):'';default:return ''}}
function styles(){if(document.getElementById('rv1AssetStyles'))return;const s=document.createElement('style');s.id='rv1AssetStyles';s.textContent=`.rv1-block{border:1px solid #c8dbe7;border-radius:18px;background:#fff;padding:14px;margin:14px 0;box-shadow:0 8px 22px rgba(15,35,55,.045)}.rv1-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}.rv1-head h4{margin:0;color:var(--primary,#0f4c75)}.rv1-pill{display:inline-flex;align-items:center;border-radius:999px;padding:4px 8px;background:#eef5ff;color:#214d86;border:1px solid #c6d9ef;font-size:.68rem;font-weight:900;letter-spacing:.05em}.rv1-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.rv1-grid.single{grid-template-columns:1fr}.rv1-asset.wide{grid-column:1/-1}.rv1-asset{margin:0;border:1px solid #d8e4ef;border-radius:14px;overflow:hidden;background:#f8fbfc;min-width:0}.rv1-asset figcaption{font-weight:900;color:#102a43;padding:10px 12px;background:#fff;border-bottom:1px solid #d8e4ef}.rv1-asset a{display:block;background:#f2f6f9}.rv1-asset img{width:100%;height:auto;display:block;object-fit:contain}.rv1-prov{font-size:.68rem;color:#69798d;padding:7px 10px;background:#fff;border-top:1px solid #e6edf3}.rv1-plan{border-color:#d9c999;background:linear-gradient(180deg,#fff,#fffbf1)}.rv1-validation{border-color:#9dc7e8;background:linear-gradient(180deg,#fff,#f5faff)}.rv1-complete{border-color:#9dd9b7;background:linear-gradient(180deg,#fff,#f4fff7)}@media(max-width:1000px){.rv1-grid{grid-template-columns:1fr}.rv1-asset.wide{grid-column:auto}}`;document.head.appendChild(s)}
